/* Nikoleta Wellness CEO — Learning Center. Local-first MVP; no cloud or paid API. */
const DB='NikoletaLearningCenter',VER=1,STORE='records';
let db,recorder=null,stream=null,recordParts=[],recordStarted=0,elapsedBefore=0,timerHandle=null,currentId=null;
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=s=>new Date(s).toLocaleString('el-GR',{dateStyle:'medium',timeStyle:'short'});
const fmtTime=s=>{s=Math.floor(s||0);return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(n=>String(n).padStart(2,'0')).join(':')};
function openDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open(DB,VER);q.onupgradeneeded=()=>{const d=q.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE,{keyPath:'id'})};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
function all(){return new Promise((resolve,reject)=>{const q=db.transaction(STORE).objectStore(STORE).getAll();q.onsuccess=()=>resolve(q.result||[]);q.onerror=()=>reject(q.error)})}
function put(v){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(v);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function del(id){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function clearRecords(){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
function replaceAll(records){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite'),store=tx.objectStore(STORE);store.clear();records.forEach(v=>store.put(v));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Η επαναφορά ακυρώθηκε'))})}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function showHome(){ $('home').classList.remove('hidden');$('view').classList.add('hidden');renderRecent();currentId=null}
function showView(html){$('home').classList.add('hidden');$('view').classList.remove('hidden');$('view').innerHTML=html;window.scrollTo(0,0)}
async function runGlobalSearch(term){const box=$('searchResults');if(!box)return;const q=term.trim().toLocaleLowerCase('el');if(!q){box.textContent='Γράψε μια λέξη για να βρεις τις αποθηκευμένες καταχωρίσεις σου.';return}const rows=await all();const hits=[];for(const x of rows){const fields=[x.title,x.speaker,x.description,x.body,x.transcript,x.notes,x.summary,x.learning,x.personal];const match=fields.some(v=>String(v||'').toLocaleLowerCase('el').includes(q));if(match)hits.push(x)}box.innerHTML=hits.length?hits.slice(0,15).map(x=>'<div class="fileitem"><div><strong>'+esc(x.title||'Χωρίς τίτλο')+'</strong><div class="note">'+esc(x.type==='seminar'?'Σεμινάριο':(simple[x.type?.replace('module_','')]||['Καταχώριση'])[0])+' · '+fmtDate(x.updated||x.created)+'</div></div><button class="btn light" data-search-open="'+x.id+'">Άνοιγμα</button></div>').join(''):'Δεν βρέθηκαν αποτελέσματα.';document.querySelectorAll('[data-search-open]').forEach(b=>b.onclick=async()=>{const x=(await all()).find(v=>v.id===b.dataset.searchOpen);if(x?.type==='seminar')openSeminar(x.id);else if(x){const k=x.type.replace('module_','');simpleView(k)}})}
async function renderRecent(){const items=(await all()).filter(x=>x.type==='seminar').sort((a,b)=>b.updated-a.updated);$('seminarCount').textContent=items.length+' σεμινάρια';$('recentList').innerHTML=items.length?items.slice(0,5).map(s=>seminarCard(s)).join(''):'<p class="muted">Δεν έχεις δημιουργήσει ακόμη σεμινάριο.</p>';bindSeminarCards()}
function seminarCard(s){return '<div class="seminar"><div><strong>'+esc(s.title)+'</strong><small>'+fmtDate(s.created)+' · '+(s.audio?.length||0)+' αρχεία ήχου</small></div><div class="row"><span class="pill">'+esc(s.status||'Σε εξέλιξη')+'</span><button class="btn light" data-seminar="'+s.id+'">Άνοιγμα</button></div></div>'}
function bindSeminarCards(){document.querySelectorAll('[data-seminar]').forEach(b=>b.onclick=()=>openSeminar(b.dataset.seminar))}
async function audioDashboard(){const items=(await all()).filter(x=>x.type==='seminar').sort((a,b)=>b.updated-a.updated);showView('<div class="hero"><div><h2>🎙️ Audio Academy</h2><p>Όλα τα σεμινάρια, οι ηχογραφήσεις και τα εκπαιδευτικά σου αρχεία.</p></div><div class="actions"><button class="btn light" id="back">← Αρχική</button><button class="btn gold" id="createAudioSem">＋ Νέο σεμινάριο</button></div></div><div class="panel"><h3>Οι φάκελοί μου</h3>'+(items.length?items.map(s=>seminarCard(s)).join(''):'<p class="muted">Δεν υπάρχουν ακόμη φάκελοι σεμιναρίων. Δημιούργησε τον πρώτο σου.</p>')+'</div>');$('back').onclick=showHome;$('createAudioSem').onclick=newSeminar;bindSeminarCards()}
function newSeminar(){showView('<div class="hero"><div><h2>Νέο σεμινάριο</h2><p>Δημιούργησε έναν ξεχωριστό φάκελο για κάθε εκπαίδευση.</p></div><button class="btn light" id="back">← Αρχική</button></div><div class="panel"><div class="field"><label>Τίτλος σεμιναρίου</label><input id="semTitle" placeholder="π.χ. Επικοινωνία και Ηγεσία"></div><div class="field"><label>Εισηγητής / Διοργανωτής (προαιρετικά)</label><input id="semSpeaker" placeholder="Όνομα"></div><div class="field"><label>Περιγραφή</label><textarea id="semDesc" placeholder="Τι πραγματεύεται το σεμινάριο;"></textarea></div><button class="btn gold" id="createSem">Δημιουργία φακέλου</button></div>');$('back').onclick=showHome;$('createSem').onclick=async()=>{const title=$('semTitle').value.trim();if(!title){alert('Συμπλήρωσε τον τίτλο του σεμιναρίου.');return}const now=Date.now(),s={id:crypto.randomUUID(),type:'seminar',title,speaker:$('semSpeaker').value.trim(),description:$('semDesc').value.trim(),created:now,updated:now,status:'Σε εξέλιξη',audio:[],transcript:'',notes:'',summary:'',learning:'',personal:''};await put(s);openSeminar(s.id)}}
async function openSeminar(id){const s=(await all()).find(x=>x.id===id);if(!s)return showHome();currentId=id;showView('<div class="hero"><div><span class="pill">ΦΑΚΕΛΟΣ ΣΕΜΙΝΑΡΙΟΥ</span><h2>'+esc(s.title)+'</h2><p>'+fmtDate(s.created)+(s.speaker?' · '+esc(s.speaker):'')+'</p></div><div class="actions"><button class="btn light" id="backHome">← Αρχική</button><button class="btn gold" id="exportSem">Εξαγωγή υλικού</button></div></div><div class="tabs"><button class="tab active" data-tab="audioTab">🎙️ Ήχος</button><button class="tab" data-tab="textTab">📝 Κείμενο</button><button class="tab" data-tab="studyTab">🎓 Εκπαίδευση</button></div><div id="audioTab"><div class="recbox"><div class="muted">ΧΡΟΝΟΣ ΗΧΟΓΡΑΦΗΣΗΣ</div><div class="timer" id="timer">00:00:00</div><p class="note" id="recStatus">Η εγγραφή αποθηκεύεται τμηματικά στη συσκευή. Άφησε ανοιχτή την εφαρμογή κατά την ηχογράφηση.</p><div class="actions"><button class="btn gold" id="startRec">● Έναρξη</button><button class="btn light" id="pauseRec" disabled>Ⅱ Παύση</button><button class="btn light" id="resumeRec" disabled>▶ Συνέχεια</button><button class="btn danger" id="stopRec" disabled>■ Ολοκλήρωση</button></div></div><div class="panel"><h3>Ανέβασμα υπάρχουσας ηχογράφησης</h3><p class="note">Επίλεξε αρχείο ήχου από τη συσκευή. Το αρχείο θα αποθηκευτεί τοπικά στον φάκελο αυτού του σεμιναρίου.</p><input type="file" id="audioUpload" accept="audio/*,.mp3,.m4a,.wav,.ogg,.webm"><div id="audioFiles">'+audioList(s)+'</div></div></div><div id="textTab" class="hidden"><div class="panel"><h3>Πλήρης απομαγνητοφώνηση</h3><p class="note">Επικόλλησε εδώ το κείμενο που θα δημιουργήσεις με δωρεάν τοπικό εργαλείο απομαγνητοφώνησης.</p><div class="field"><textarea id="transcript" placeholder="Το πλήρες κείμενο του σεμιναρίου...">'+esc(s.transcript)+'</textarea></div><button class="btn" id="saveTranscript">Αποθήκευση κειμένου</button></div></div><div id="studyTab" class="hidden"><div class="panel"><h3>Εκπαιδευτικό υλικό</h3>'+editor('notes','Αναλυτικές σημειώσεις',s.notes,'Σημαντικά σημεία, έννοιες και παραδείγματα...')+editor('summary','Περίληψη',s.summary,'Τα βασικά συμπεράσματα του σεμιναρίου...')+editor('learning','Εκπαιδευτικό υλικό',s.learning,'Ενότητες, βήματα εφαρμογής, ασκήσεις και απαντήσεις...')+editor('personal','Προσωπικές σημειώσεις',s.personal,'Οι δικές μου παρατηρήσεις και ενέργειες...')+'<button class="btn gold" id="saveStudy">Αποθήκευση εκπαιδευτικού υλικού</button></div></div>');$('backHome').onclick=showHome;$('exportSem').onclick=()=>exportSeminar(s.id);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));['audioTab','textTab','studyTab'].forEach(k=>$(k).classList.toggle('hidden',k!==b.dataset.tab))});bindAudioActions(s);$('audioUpload').onchange=e=>uploadAudio(id,e.target.files[0]);$('saveTranscript').onclick=async()=>{s.transcript=$('transcript').value;s.updated=Date.now();await put(s);alert('Το κείμενο αποθηκεύτηκε.')};$('saveStudy').onclick=async()=>{['notes','summary','learning','personal'].forEach(k=>s[k]=$(k).value);s.updated=Date.now();await put(s);alert('Το εκπαιδευτικό υλικό αποθηκεύτηκε.')};$('startRec').onclick=()=>startRecording(id);$('pauseRec').onclick=pauseRecording;$('resumeRec').onclick=resumeRecording;$('stopRec').onclick=stopRecording}
function editor(id,label,value,placeholder){return '<div class="field"><label>'+label+'</label><textarea id="'+id+'" placeholder="'+placeholder+'">'+esc(value)+'</textarea></div>'}
function audioList(s){return s.audio?.length?s.audio.map((a,i)=>'<div class="fileitem"><div><strong>'+esc(a.name)+'</strong><div class="note">'+(a.size/1048576).toFixed(1)+' MB · '+fmtDate(a.date)+'</div></div><div class="row"><button class="btn light" data-play="'+i+'">▶ Αναπαραγωγή</button><button class="btn light" data-download="'+i+'">↓ Λήψη</button></div></div>').join(''):'<p class="muted">Δεν υπάρχουν ακόμη αρχεία ήχου.</p>'}
function bindAudioActions(s){document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{const a=s.audio[+b.dataset.play],url=URL.createObjectURL(a.blob),w=window.open('','_blank');if(w)w.document.write('<title>Αναπαραγωγή ήχου</title><audio controls autoplay src="'+url+'" style="width:95%;margin:20px"></audio>')});document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>{const a=s.audio[+b.dataset.download];download(a.blob,a.name)})}
async function refreshAudio(id){const s=(await all()).find(x=>x.id===id);$('audioFiles').innerHTML=audioList(s);bindAudioActions(s)}
async function uploadAudio(id,file){if(!file)return;const s=(await all()).find(x=>x.id===id);s.audio.push({id:crypto.randomUUID(),name:file.name,blob:file,size:file.size,date:Date.now(),kind:'upload'});s.updated=Date.now();await put(s);await refreshAudio(id);$('audioUpload').value=''}
async function startRecording(id){try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Το πρόγραμμα περιήγησης δεν υποστηρίζει ηχογράφηση.');stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);const rec=recorder,recMime=rec.mimeType,sessionId=crypto.randomUUID();recordStarted=Date.now();elapsedBefore=0;let lastChunkSave=Promise.resolve();rec.ondataavailable=e=>{if(!e.data?.size)return;lastChunkSave=lastChunkSave.then(async()=>{const s=(await all()).find(x=>x.id===id);s.audio.push({id:crypto.randomUUID(),sessionId,name:'Προσωρινό τμήμα '+(s.audio.filter(a=>a.sessionId===sessionId).length+1),blob:e.data,size:e.data.size,date:Date.now(),kind:'recording-part'});s.updated=Date.now();await put(s)})};rec.onerror=()=>{$('recStatus').textContent='Παρουσιάστηκε σφάλμα ηχογράφησης. Τα ήδη αποθηκευμένα προσωρινά τμήματα διατηρούνται.'};rec.onstop=async()=>{try{await lastChunkSave;const s=(await all()).find(x=>x.id===id);const parts=s.audio.filter(a=>a.sessionId===sessionId).sort((a,b)=>a.date-b.date);if(parts.length){const blob=new Blob(parts.map(a=>a.blob),{type:recMime||'audio/webm'});s.audio=s.audio.filter(a=>a.sessionId!==sessionId);const ext=recMime.includes('mp4')?'m4a':'webm';s.audio.push({id:crypto.randomUUID(),name:'Ηχογράφηση_'+new Date().toISOString().replace(/[:.]/g,'-')+'.'+ext,blob,size:blob.size,date:Date.now(),kind:'recording'});s.updated=Date.now();await put(s)}if($('audioFiles'))await refreshAudio(id);if($('recStatus'))$('recStatus').textContent='Η ηχογράφηση ολοκληρώθηκε και αποθηκεύτηκε ως ενιαίο αρχείο.'}catch(err){if($('recStatus'))$('recStatus').textContent='Δεν ολοκληρώθηκε η σύνθεση του αρχείου. Έλεγξε τα προσωρινά τμήματα και τον διαθέσιμο χώρο.'}};rec.start(60000);$('startRec').disabled=true;$('pauseRec').disabled=false;$('stopRec').disabled=false;$('recStatus').textContent='Ηχογράφηση σε εξέλιξη. Τα δεδομένα αποθηκεύονται προσωρινά ανά περίπου λεπτό και ενώνονται στο τέλος.';timerHandle=setInterval(()=>$('timer').textContent=fmtTime(elapsedBefore+(rec?.state==='recording'?(Date.now()-recordStarted)/1000:0)),500)}catch(e){alert('Δεν ξεκίνησε η ηχογράφηση: '+e.message+'\\nΈλεγξε την άδεια μικροφώνου και άνοιξε την εφαρμογή μέσω HTTPS.')}}
function pauseRecording(){if(recorder?.state==='recording'){elapsedBefore+=(Date.now()-recordStarted)/1000;recorder.pause();$('pauseRec').disabled=true;$('resumeRec').disabled=false;$('recStatus').textContent='Η ηχογράφηση είναι σε παύση.'}}
function resumeRecording(){if(recorder?.state==='paused'){recordStarted=Date.now();recorder.resume();$('pauseRec').disabled=false;$('resumeRec').disabled=true;$('recStatus').textContent='Ηχογράφηση σε εξέλιξη.'}}
function stopRecording(){if(!recorder)return;recorder.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;clearInterval(timerHandle);$('startRec').disabled=false;$('pauseRec').disabled=true;$('resumeRec').disabled=true;$('stopRec').disabled=true;$('recStatus').textContent='Η ηχογράφηση ολοκληρώθηκε. Τα τμήματα αποθηκεύτηκαν στον φάκελο. Μπορείς να τα κατεβάσεις ξεχωριστά.'}
async function exportSeminar(id){const s=(await all()).find(x=>x.id===id);if(!s)return;const stamp=new Date(s.created||Date.now()).toLocaleString('el-GR');const text='ΣΕΜΙΝΑΡΙΟ: '+s.title+'\\nΕισηγητής: '+(s.speaker||'—')+'\\nΗμερομηνία: '+stamp+'\\n\\nΠΕΡΙΓΡΑΦΗ\\n'+(s.description||'—')+'\\n\\nΠΛΗΡΗΣ ΑΠΟΜΑΓΝΗΤΟΦΩΝΗΣΗ\\n'+(s.transcript||'Δεν έχει προστεθεί κείμενο.')+'\\n\\nΑΝΑΛΥΤΙΚΕΣ ΣΗΜΕΙΩΣΕΙΣ\\n'+(s.notes||'—')+'\\n\\nΠΕΡΙΛΗΨΗ\\n'+(s.summary||'—')+'\\n\\nΕΚΠΑΙΔΕΥΤΙΚΟ ΥΛΙΚΟ\\n'+(s.learning||'—')+'\\n\\nΠΡΟΣΩΠΙΚΕΣ ΣΗΜΕΙΩΣΕΙΣ\\n'+(s.personal||'—');const html='<!doctype html><html lang="el"><meta charset="utf-8"><title>'+esc(s.title)+'</title><style>body{font-family:Arial,sans-serif;max-width:850px;margin:40px auto;line-height:1.65;color:#17392c}h1{color:#0b5036;border-bottom:3px solid #c9a65b;padding-bottom:12px}h2{color:#176b49;margin-top:28px}pre{white-space:pre-wrap;font:inherit}</style><h1>'+esc(s.title)+'</h1><p><b>Εισηγητής:</b> '+esc(s.speaker||'—')+'<br><b>Ημερομηνία:</b> '+esc(stamp)+'</p>'+[['Περιγραφή',s.description],['Πλήρης απομαγνητοφώνηση',s.transcript],['Αναλυτικές σημειώσεις',s.notes],['Περίληψη',s.summary],['Εκπαιδευτικό υλικό',s.learning],['Προσωπικές σημειώσεις',s.personal]].map(([h,v])=>'<h2>'+h+'</h2><pre>'+esc(v||'—')+'</pre>').join('')+'</html>';download(new Blob([html],{type:'application/msword;charset=utf-8'}),safe(s.title)+'_Εκπαιδευτικό_Υλικό.doc');download(new Blob([text],{type:'text/plain;charset=utf-8'}),safe(s.title)+'_Κείμενο.txt');const meta={...s,audio:s.audio.map(a=>({id:a.id,name:a.name,size:a.size,date:a.date,kind:a.kind}))};download(new Blob([JSON.stringify(meta,null,2)],{type:'application/json'}),safe(s.title)+'_δεδομένα.json');for(const a of s.audio)download(a.blob,safe(s.title)+'_'+a.name)}
function safe(s){return String(s||'seminar').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').slice(0,60)}
function blobToDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)})}
function dataURLToBlob(data){const [head,body]=data.split(',');const mime=(head.match(/data:([^;]+)/)||[])[1]||'application/octet-stream';const raw=atob(body);const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Blob([bytes],{type:mime})}
async function backup(){try{const items=await all();const total=items.reduce((n,s)=>n+(s.audio||[]).reduce((m,a)=>m+(a.size||0),0),0);if(total>300*1024*1024&&!confirm('Τα αρχεία ήχου είναι περίπου '+(total/1048576).toFixed(0)+' MB. Η δημιουργία αντιγράφου μπορεί να χρειαστεί αρκετή μνήμη. Συνέχεια;'))return;const records=[];for(const s of items){const copy={...s,audio:[]};for(const a of (s.audio||[])){copy.audio.push({...a,blobData:a.blob?await blobToDataURL(a.blob):null,blob:undefined})}if(s.fileBlob){copy.fileBlobData=await blobToDataURL(s.fileBlob);copy.fileBlob=undefined}records.push(copy)}const pack={format:'nikoleta-learning-center',version:2,created:new Date().toISOString(),recordCount:records.length,audioBytes:total,records};download(new Blob([JSON.stringify(pack)],{type:'application/json'}),'Nikoleta_Learning_Center_FULL_Backup_'+new Date().toISOString().slice(0,10)+'.json');alert('Το πλήρες αντίγραφο δημιουργήθηκε. Περιλαμβάνει κείμενα, σημειώσεις και ηχογραφήσεις. Κράτησέ το σε δύο διαφορετικά σημεία.')}catch(e){alert('Δεν ολοκληρώθηκε το αντίγραφο: '+e.message+'\\nΔοκίμασε ξανά με μικρότερα αρχεία ήχου.')}} 
async function storageInfo(){let html='';try{const e=await navigator.storage?.estimate?.();if(e){html='<p class="note">Χρήση χώρου: '+((e.usage||0)/1048576).toFixed(1)+' MB · Διαθέσιμο όριο περίπου '+((e.quota||0)/1048576).toFixed(0)+' MB</p>'}}catch{}return html}
async function settings(){const durable=await navigator.storage?.persist?.().catch(()=>false);const info=await storageInfo();showView('<div class="hero"><div><h2>Ρυθμίσεις & Μεταφορά</h2><p>Σχεδιασμένη για αλλαγή κινητού και υπολογιστή.</p></div><button class="btn light" id="back">← Αρχική</button></div><div class="panel"><h3>🛡️ Προστασία δεδομένων</h3><p>'+(durable?'Το πρόγραμμα περιήγησης ενέκρινε προστατευμένη τοπική αποθήκευση.':'Τα δεδομένα παραμένουν τοπικά. Η προστασία από αυτόματη εκκαθάριση εξαρτάται από τη συσκευή.')+'</p>'+info+'<p class="note">Η εφαρμογή δεν συγχρονίζει αυτόματα μεταξύ συσκευών. Για να μη χαθούν αρχεία, δημιούργησε τακτικά πλήρες αντίγραφο και φύλαξέ το εκτός κινητού.</p><button class="btn gold" id="backupNow">⬇ Δημιουργία ΠΛΗΡΟΥΣ αντιγράφου (με ήχους)</button></div><div class="panel" style="margin-top:14px"><h3>📥 Επαναφορά σε νέα συσκευή</h3><p>Επίλεξε το πλήρες αρχείο JSON που δημιούργησες από την παλιά συσκευή. Η επαναφορά αντικαθιστά τα δεδομένα της εφαρμογής στη νέα συσκευή.</p><div class="field"><label>Αρχείο αντιγράφου ασφαλείας</label><input id="restoreFile" type="file" accept=".json,application/json"></div><button class="btn" id="restoreNow">Επαναφορά δεδομένων</button></div><div class="panel" style="margin-top:14px"><h3>🔌 Μεταφορά μέσω USB</h3><ol><li>Σύνδεσε το παλιό κινητό στον υπολογιστή με USB.</li><li>Επίλεξε «Μεταφορά αρχείων» στο κινητό.</li><li>Αντέγραψε το αρχείο πλήρους αντιγράφου σε φάκελο του υπολογιστή.</li><li>Σύνδεσε το νέο κινητό και αντέγραψε εκεί το ίδιο αρχείο.</li><li>Άνοιξε τη νέα εφαρμογή και επίλεξε «Επαναφορά δεδομένων».</li></ol><p class="note">Κράτησε επίσης ένα δεύτερο αντίγραφο σε USB flash drive ή εξωτερικό δίσκο. Μην βασιστείς μόνο σε μία συσκευή.</p></div>');$('back').onclick=showHome;$('backupNow').onclick=backup;$('restoreNow').onclick=()=>restore({target:{files:[$('restoreFile').files[0]]}})}
async function restore(e){const f=e.target.files?.[0];if(!f)return;try{if(f.size>1024*1024*1024)throw Error('Το αντίγραφο είναι μεγαλύτερο από 1 GB. Χώρισέ το σε μικρότερα αντίγραφα.');const data=JSON.parse(await f.text());if(data.format!=='nikoleta-learning-center'||!Array.isArray(data.records))throw Error('Μη έγκυρο αρχείο αντιγράφου.');if(!confirm('Θα εισαχθούν '+data.records.length+' εγγραφές. Τα υπάρχοντα δεδομένα σε αυτή τη συσκευή θα αντικατασταθούν. Έχεις κρατήσει αντίγραφο των τωρινών δεδομένων;'))return;const restored=data.records.map(item=>{const z={...item,audio:(item.audio||[]).map(a=>{const q={...a};if(a.blobData){q.blob=dataURLToBlob(a.blobData);delete q.blobData}return q})};if(item.fileBlobData){z.fileBlob=dataURLToBlob(item.fileBlobData);delete z.fileBlobData}return z});await replaceAll(restored);alert('Η επαναφορά ολοκληρώθηκε. Βρέθηκαν '+data.records.length+' εγγραφές.');showHome()}catch(err){alert('Δεν έγινε η επαναφορά: '+err.message)}}
